write('results.json',dict(schemaVersion=1,state='UNAPPLIED_COMBINED355_NATIVE_INTEGRATION_SOURCE_CANDIDATE_V1',sourceOnly=True,sourcePrepared=True,sourceChecksPassed=True,independentSourceReview=None,nativeSourceFiles=355,retainedParentNativeFiles=348,changedNativeFiles=7,externalEmbeddingSources=3,selectedManifestCount=11,expectedPolicyCppCommands=62,expectedCompileDatabaseRows=68,expectedStrictCommands=4,expectedPrivateCommands=6,expectedSeparateEmbeddingCommands=1,toolRows=checked['toolRows'],donorAuthenticationRows=checked['donorAuthenticationRows'],inputRows=len(load(HERE/'input-hashes.json')['files']),initialVariant='normal-off',contexts=contexts,artifacts=artifacts,pureSyntheticMetadataCounterexamples=len(checked['syntheticMetadataCounterexamples']),sourceDataPureGrammarChecks=checked['checks'],privateBackendEvidenceHookEnabled=False,remainingZlibRecordedDifferences=15,remainingZlibDeviationsApproved=False,producerExecuted=False,ownerHelpersImported=False,compilerInvoked=False,engineExecuted=False,guestExecuted=False,stage=None,build=None,metadataProduced=False,freeze=None,export=None,reviewedPins=None,bootstrap=None,component=None,runtime=None,operationalAdmission=False))
